/**
 * Standard import format v1 (Phase 2). Single source of truth for column
 * rules; mirrors the "Kamus Kolom" in samples/phase-2/Template_Standar_Impor.xlsx
 * (generated by scripts/samples/generate_phase2_samples.py).
 */
export const MARKETPLACE_CHANNELS = ["shopee", "tiktok_shop", "tokopedia"] as const;
export type MarketplaceChannel = (typeof MARKETPLACE_CHANNELS)[number];

export type ColumnType =
  | "date" // YYYY-MM-DD
  | "month" // YYYY-MM
  | "channel"
  | "text"
  | "integer"; // whole number, no separators/abbreviations

export type ColumnSpec = {
  name: string;
  label: string;
  type: ColumnType;
  required: boolean;
  /** Inclusive lower bound for integers (default 0). */
  min?: number;
  maxLength?: number;
  /** Date column that must not be after the upload date. */
  notFuture?: boolean;
};

export type TemplateKey = "kinerja_toko_harian" | "kinerja_produk_harian" | "target_bulanan" | "master_listing";

/** import_batches.report_type values. */
export type DbReportType =
  "marketplace_sales_daily" | "marketplace_product_performance" | "sales_target" | "channel_listing_master";

export type TemplateSpec = {
  key: TemplateKey;
  title: string;
  dbReportType: DbReportType;
  columns: ColumnSpec[];
  /** Natural key columns (unique within a file). */
  keyColumns: string[];
  /** Column holding the period (for batch period_start/period_end). */
  periodColumn?: string;
};

const ID = 128;

